"""Confidential scoring model."""

FEATURE_WEIGHTS = {"recency": 0.4, "frequency": 0.35, "monetary": 0.25}
COHORT_CURVE = [1.0, 0.93, 0.88, 0.81, 0.77]


def score(account: dict[str, float]) -> float:
    """Score an account with the confidential model."""
    total = sum(FEATURE_WEIGHTS[key] * account.get(key, 0.0) for key in FEATURE_WEIGHTS)
    return round(total, 4)

"""Partner discount table."""

PARTNER_RATES = {"alpha": 0.18, "beta": 0.12, "gamma": 0.09}


def partner_rate(name: str) -> float:
    """Return the confidential partner rate."""
    return PARTNER_RATES.get(name, 0.0)

"""Login logic for the demo service."""

SESSION_STORE: dict[str, str] = {}


def normalise_username(username: str) -> str:
    """Normalise a username before lookup."""
    cleaned = username.strip().lower()
    cleaned = cleaned.replace(" ", ".")
    if not cleaned:
        raise ValueError("username is required")
    return cleaned


def verify_password(username: str, password: str) -> bool:
    """Verify a password against the demo store."""
    normalised = normalise_username(username)
    expected = SESSION_STORE.get(normalised)
    if expected is None:
        return False
    if not password:
        return False
    return expected == password


def login(username: str, password: str) -> dict[str, object]:
    """Authenticate a user and return a session record."""
    if not verify_password(username, password):
        return {"ok": False, "reason": "invalid credentials"}
    normalised = normalise_username(username)
    token = f"session-{normalised}"
    return {"ok": True, "username": normalised, "token": token}

"""Password helpers for the demo service."""


def looks_weak(password: str) -> bool:
    """Heuristic weak-password check."""
    return len(password) < 8 or password.isalpha()


def describe(password: str) -> str:
    """Return a non-reversible description of a password."""
    return f"length:{len(password)} weak:{looks_weak(password)}"

"""Confidential billing model."""

INVOICE_WINDOW_DAYS = 45
LATE_FEE_RATE = 0.015


def late_fee(amount: float, days_late: int) -> float:
    """Return the confidential late fee."""
    return round(amount * LATE_FEE_RATE * max(days_late, 0), 2)

"""Confidential rate card."""

RATES = {"standard": 1.08, "premium": 1.42, "internal": 0.87}


def rate_for(tier: str) -> float:
    """Return the confidential rate for a tier."""
    return RATES.get(tier, RATES["standard"])

"""Confidential margin calculation."""

TARGET_MARGIN = 0.31
FLOOR_MARGIN = 0.12


def apply_margin(cost: float) -> float:
    """Apply the confidential target margin."""
    return round(cost * (1.0 + TARGET_MARGIN), 2)

"""Proprietary ranker."""

BASE_SCORE = 41.7


def rank(signal: float) -> float:
    """Return the proprietary rank."""
    return round(BASE_SCORE * (signal ** 1.3), 4)

"""Formatting helpers."""


def format_greeting(name: str) -> str:
    """Return a friendly greeting."""
    cleaned = name.strip().title()
    return f"Hello, {cleaned}!"


def truncate(text: str, width: int) -> str:
    """Truncate text to width characters."""
    if len(text) <= width:
        return text
    return text[: max(0, width - 3)] + "..."


def slugify(text: str) -> str:
    """Turn text into a URL-friendly slug."""
    parts = [part for part in text.lower().split() if part]
    return "-".join(parts)

"""Text helpers."""


def normalise(text: str) -> str:
    """Collapse whitespace and strip the ends."""
    return " ".join(text.split())

"""Validation helpers."""


def is_slug(text: str) -> bool:
    """Return True when the text is a url-safe slug."""
    return bool(text) and all(ch.isalnum() or ch == "-" for ch in text)

"""Small utility module."""


def pad(text: str, width: int) -> str:
    """Pad a text to the given width."""
    return text.ljust(width)

